import{_ as a,o as r,c as e,a3 as o}from"./chunks/framework.Dj4Lt7vj.js";const g=JSON.parse('{"title":"购买套餐和加油包","description":"","frontmatter":{"title":"购买套餐和加油包"},"headers":[],"relativePath":"billing/purchase.md","filePath":"billing/purchase.md","lastUpdated":1787949005000}'),l={name:"billing/purchase.md"};function i(n,t,s,d,h,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="购买套餐和加油包" tabindex="-1">购买套餐和加油包 <a class="header-anchor" href="#购买套餐和加油包" aria-label="Permalink to &quot;购买套餐和加油包&quot;">​</a></h1><p>目前<strong>不支持在线支付</strong>。购买通过销售完成，之后由销售直接开通或发兑换码自助兑换。</p><h2 id="购买流程" tabindex="-1">购买流程 <a class="header-anchor" href="#购买流程" aria-label="Permalink to &quot;购买流程&quot;">​</a></h2><ol><li><strong>选档位</strong>：在客户端「账单」页查看各套餐和加油包的说明，或直接把需要接入的客服账号数量、日咨询量告诉销售，让销售推荐。</li><li><strong>联系销售</strong>：通过客户端菜单里的「联系我们」，或官网上的联系方式。</li><li><strong>确认并付款</strong>：与销售确认档位、时长和价格后付款。</li><li><strong>到账</strong>：销售直接开通到你的账号，或发兑换码由你在「账单」页自助兑换，见<a href="/aicare-docs/billing/redeem">兑换码</a>。</li></ol><h2 id="买套餐还是买加油包" tabindex="-1">买套餐还是买加油包 <a class="header-anchor" href="#买套餐还是买加油包" aria-label="Permalink to &quot;买套餐还是买加油包&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>建议</th></tr></thead><tbody><tr><td>长期日常使用</td><td>订阅套餐，周期点数单价更低</td></tr><tr><td>套餐点数在周期结束前用完</td><td>补一个加油包，下周期再评估是否升档</td></tr><tr><td>大促期间临时放量</td><td>加油包，避免为短期峰值长期升档</td></tr><tr><td>试用观望</td><td>从小档位或小加油包开始</td></tr></tbody></table><p>普通点数加油包只补充客服接待点数，不包含运营助手额度。运营助手额度按自然月单独计算，具体以「账单」页为准。</p><p>套餐与点数的关系见<a href="/aicare-docs/start/plan">套餐与开通</a>和<a href="/aicare-docs/billing/points">点数怎么计算</a>。</p><h2 id="续费与升级" tabindex="-1">续费与升级 <a class="header-anchor" href="#续费与升级" aria-label="Permalink to &quot;续费与升级&quot;">​</a></h2><ul><li><strong>续费</strong>：套餐到期前联系销售续费，或兑换新的套餐码。</li><li><strong>升级</strong>：需要更多客服账号接入位、更多方案，或需要情景分流、表格、商品智能整理等按套餐开放的能力时，联系销售换档。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>能开发票吗？</strong> 和销售确认，按公司流程开具。</p><p><strong>价格在哪看？</strong> 「账单」页展示各档位说明，最终价格以销售报价为准。</p>',13)])])}const u=a(l,[["render",i]]);export{g as __pageData,u as default};
